import{_ as s,a0 as d,w as i,s as a,ao as u,I as r,x as n,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux基础：如何在命令行中查看目录的大小 | LCTT x X-CMD","titleTemplate":false,"description":"Linux基础：如何在命令行中查看目录的大小 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux基础：如何在命令行中查看目录的大小 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux基础：如何在命令行中查看目录的大小 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140711 Linux Basics--How To Find Size of Directory Commands","title":"Linux基础：如何在命令行中查看目录的大小","tag":"201407","desc":""},"relativePath":"201407/20140711 Linux Basics--How To Find Size of Directory Commands.md","filePath":"[post].md"}'),l={name:"201407/20140711 Linux Basics--How To Find Size of Directory Commands.md"};function m(g,t,c,x,T,f){const o=d("Link");return i(),a("div",null,[t[11]||(t[11]=u(`<h1 id="linux基础-如何在命令行中查看目录的大小" tabindex="-1">Linux基础：如何在命令行中查看目录的大小 <a class="header-anchor" href="#linux基础-如何在命令行中查看目录的大小" aria-label="Permalink to “Linux基础：如何在命令行中查看目录的大小”">​</a></h1><p>这是写给Liunx新用户的一系列文章中的第一篇，在这系列文章我将会写一些对新用户来说非常好用的<strong>Linux基础命令</strong>。</p><p><strong>注意</strong>：本文的目标读者是仅有小量甚至是没有任何Linux命令行使用经验的读者。</p><blockquote><p>作为一个Linux的新用户，我怎样可以在命令行终端中查看某个目录的属性？</p></blockquote><p>###要求###</p><p>唯一的要求是<strong>du</strong>命令行工具。du基本上是所有Linux发行版本默认提供的工具。用以下的命令来检查你的系统中是否可以使用du命令：</p><pre><code>man du
</code></pre><p><strong>du</strong> 命令用于输出文件的空间使用情况。</p><p>###使用du###</p><p>不带任何参数的运行du命令会显示当前工作目录以及其子目录的文件名和所占用的空间大小(以字节为单位)。</p><pre><code>du
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-overview.png" alt=""></p><p>使用<strong>-h</strong>参数以对用户友好的方式输出文件大小，即分别以<strong>K, M</strong>和<strong>G</strong>来表示<strong>Kb,Mb</strong>和<strong>Gb</strong></p><pre><code>du -h
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-h.png" alt=""></p><p>若想查看某个特定目录的文件大小，则在du命令中指定要查看的目录名，如下：</p><pre><code>du -h Mapmaker
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-h-mapmaker.png" alt=""></p><p>使用 <strong>-c</strong> 参数来查看目录所占用磁盘空间的总大小</p><pre><code>du -ch
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-ch.png" alt=""></p><p>使用 <strong>-s</strong> 参数只输出指定目录占用空间的大小</p><pre><code>du -sh Mapmaker Sandbox
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/du-ch.png" alt=""></p><p>使用 man du 查看du命令更多参数的用法</p><pre><code>man du
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/man-du.png" alt=""></p><p>知道du命令更多的用法？请分享给我和其他人。</p><hr>`,29)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://www.unixmen.com/linux-basics-find-size-directory-commands/"},{default:p(()=>[...t[0]||(t[0]=[n("http://www.unixmen.com/linux-basics-find-size-directory-commands/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=n("译者：",-1)),e(o,{href:"https://github.com/cvsher"},{default:p(()=>[...t[2]||(t[2]=[n("cvsher",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const h=s(l,[["render",m]]);export{C as __pageData,h as default};
